    #[tokio::test]
    async fn read_file_tool_returns_contents() {
        let fx = Fixture::new();
        let tool = builtin_read_file(fx.tree());
        let out = tool
            .execute(serde_json::json!({ "path": "src/main.rs" }))
            .await
